package com.github.hcsp.io;

import java.io.File;
import java.io.FileFilter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class FileSearch {
    // 找到主文件夹中所有扩展名是.jpg、.png、.gif、.jpeg的图片文件，并返回文件的路径列表
    public static List<String> search(String folderPath) throws IOException {
        List<String> result = new ArrayList<>();
        File file = new File(folderPath);
        File[] files = file.listFiles(new FileFilter() {
            @Override
            public boolean accept(File pathname) {
                return pathname.isFile() && (pathname.getName().endsWith(".jpg") || pathname.getName().endsWith(".png") || pathname.getName().endsWith(".gif") || pathname.getName().endsWith(".jpeg"));
            }
        });
        for (File file1 : files) {
            result.add(file1.getAbsolutePath());
        }
        return result;
    }

    // 找到主文件夹中所有扩展名是.jpg、.png、.gif、.jpeg的图片文件，并返回文件的路径列表
    public static List<String> search2(String folderPath) throws IOException {
        List<String> result = new ArrayList<>();
        Path path = Paths.get(folderPath);
        Files.walk(path).forEach(path1 -> {
            if (Files.isRegularFile(path1) && (path1.toString().endsWith(".jpg") || path1.toString().endsWith(".png") || path1.toString().endsWith(".gif") || path1.toString().endsWith(".jpeg"))) {
                result.add(path1.toString());
            }
        });
        return result;
    }

    public static void main(String[] args) throws IOException {
        System.out.println(search2("E:\\Java\\Java_Learning\\Java_Learning\\src\\main\\java\\com\\github\\hcsp\\io"));
    }
}
