package com.github.javaparser.utils;

import java.io.File;
import java.io.IOException;
import java.nio.charset.Charset;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class SourceCode {
    private static final String SOURCE_CODE_PATH = "src/main/resources/source_code/";
    private static final String SOURCE_CODE_EXTENSION = ".java";

    public static List<String> getSourceCode(String sourceCodeName) {
        List<String> sourceCode = new ArrayList<>();
        try {
            sourceCode = Files.readAllLines(Paths.get(SOURCE_CODE_PATH + sourceCodeName + SOURCE_CODE_EXTENSION), Charset.defaultCharset());
        } catch (IOException e) {
            e.printStackTrace();
        }
        return sourceCode;
    }

    public static String getSourceCodeAsString(String sourceCodeName) {
        return String.join("\n", getSourceCode(sourceCodeName));
    }

    public static String getSourceCodeAsString(File sourceCodeFile) {
        return String.join("\n", getSourceCode(sourceCodeFile));
    }

    public static String getSourceCodeAsString(String sourceCodeName, String sourceCodeExtension) {
        return String.join("\n", getSourceCode(sourceCodeName, sourceCodeExtension));
    }

    public static List<String> getSourceCode(String sourceCodeName, String sourceCodeExtension) {
        List<String> sourceCode = new ArrayList<>();
        try {
            sourceCode = Files.readAllLines(Paths.get(SOURCE_CODE_PATH + sourceCodeName + sourceCodeExtension), Charset.defaultCharset());
        } catch (IOException e) {
            e.printStackTrace();
        }
        return sourceCode;
    }

    public static List<String> getSourceCode(File sourceCodeFile) {
        List<String> sourceCode = new ArrayList<>();
        try {
            sourceCode = Files.readAllLines(Paths.get(sourceCodeFile.getAbsolutePath()), Charset.defaultCharset());
        } catch (IOException e) {
            e.printStackTrace();
        }
        return sourceCode;
    }
