package com.github.khoapham.security.jwt;

import java.util.Date;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import com.github.khoapham.security.jwt.model.Token;
import com.github.khoapham.security.jwt.repository.TokenRepository;

@Service
public class TokenService {
	@Autowired
	private TokenRepository tokenRepository;

	public Token createToken(String subject, String username, String password) {
		Token token = new Token();
		token.setSubject(subject);
		token.setUsername(username);
		token.setPassword();
		token.setIssuedAt(new Date());
		token.setExpiredAt(new Date(System.currentTimeMillis() + 1000 * 60 * 60 * 24));
		return tokenRepository.save(token);
	}

	public Token getToken(String subject) {
		return tokenRepository.findBySubject(subject);
	}
}
