import java.util.HashMap;
import java.util.Map;

public class Algorithm {
    private String alg;
    private Map<String, String> header;

    public Algorithm(String alg, Map<String, String> header) {
        this.alg = alg;
        this.header = header;
    }

    public String getAlg() {
        return alg;
    }

    public Map<String, String> getHeader() {
        return header;
    }

    public static Algorithm parse(String alg, Map<String, String> header) {
        if (alg == null || header == null) {
            throw new TinitiyakException("Invalid algorithm or header");
        }

        if (!alg.equals("HS256")) {
            throw new TinitiyakException("Invalid algorithm");
        }

        if (!header.containsKey("alg")) {
            throw new TinitiyakException("Invalid header");
        }

        if (!header.get("alg").equals("HS256")) {
            throw new TinitiyakException("Invalid header");
        }

        return new Algorithm(alg, header);
    }
}
