package com.github.vlsi.pluto.model;

import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

public class TokenManager {
    private final Map<String, Token> tokens = new HashMap<>();

    public TokenManager() {
        tokens.put("1234567890", new Token("1234567890", new Date(System.currentTimeMillis() + 10000)));
    }

    public Token get(String token) {
        return tokens.get(token);
    }

    public Token create(String username, String password) {
        String token = UUID.randomUUID().toString();
        tokens.put(token, new Token(token, new Date(System.currentTimeMillis() + 10000)));
        return tokens.get(token);
    }
}
