public class FindTheParityOutlier {
    public static int find(int[] integers) {
        int even = 0;
        int odd = 0;
        for (int i = 0; i < integers.length; i++) {
            if (integers[i] % 2 == 0) {
                even++;
            } else {
                odd++;
            }
        }
        if (even > odd) {
            for (int i = 0; i < integers.length; i++) {
                if (integers[i] % 2!= 0) {
                    return integers[i];
                }
            }
        } else {
            for (int i = 0; i < integers.length; i++) {
                if (integers[i] % 2 == 0) {
                    return integers[i];
                }
            }
        }
        return 0;
    }
}
