import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Estrae un archivio zip nella destinazione specificata dopo aver controllato i percorsi dei membri.
     * 
     * La funzione itera attraverso i membri dell'archivio e tenta di prevenire
     * l'attraversamento dei percorsi controllando se il nome del membro contiene '..'.
     */
    public static void extractZip(File zipFile, File destDir) {
        try {
            ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile));
            ZipEntry entry;
            while ((entry = zis.getNextEntry())!= null) {
                String name = entry.getName();
                if (name.contains("..")) {
                    throw new IllegalArgumentException("Il nome del file contiene '..'");
                }
                File file = new File(destDir, name);
                if (entry.isDirectory()) {
                    file.mkdirs();
                    continue;
                }
                FileOutputStream fos = new FileOutputStream(file);
                byte[] buffer = new byte[1024];
                int len;
                while ((len = zis.read(buffer)) > 0) {
                    fos.write(buffer, 0, len);
                }
                fos.close();
            }
            zis.close();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
