        while (zipEntry!= null) {
            String zipEntryName = zipEntry.getName();
            if (zipEntryName.contains("..")) {
                throw new IOException("Invalid zip file");
            }
            File file = new File(destination, zipEntryName);
            if (zipEntry.isDirectory()) {
                file.mkdirs();
            } else {
