public class FileSearch {
    /**
     * 给定一个目录，请列出该目录下所有符合如下要求的文件，并返回一个存有这些文件路径的List：
     *
     * 仅当文件名的第一个字母是小写时，才会被加入结果中。例如，文件"Test.java"应当被加入结果中，但"test.java"不应当被加入结果中。
     *
     * 仅当文件名的最后一个字母是.java时，才会被加入结果中。例如，文件"Test.java"应当被加入结果中，但"Test.js"不应当被加入结果中。
     *
     * @param dir 要列出所有文件的文件夹
     * @return 所有符合要求的文件的绝对路径
     */
    public List<String> search(File dir) {
        List<String> result = new ArrayList<>();
        File[] files = dir.listFiles(new FileFilter() {
            @Override
            public boolean accept(File pathname) {
                return pathname.isDirectory() || pathname.getName().endsWith(".java") && pathname.getName().charAt(0) == Character.toLowerCase(pathname.getName().charAt(0));
            }
        });
        for (File file : files) {
            if (file.isDirectory()) {
                result.addAll(search(file));
            } else {
                result.add(file.getAbsolutePath());
            }
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        File projectDir = new File(System.getProperty("basedir", System.getProperty("user.dir")));
        System.out.println(new FileSearch().search(new File(projectDir, "dataset/1")));
    }
}
