private static void copy(File source, File destination) throws Exception {
    if (source.getName().contains("..")) {
        return;
    }
    if (source.isDirectory()) {
        if (!destination.exists()) {
            destination.mkdirs();
        }
        for (File file : source.listFiles()) {
            String newPath = destination.getAbsolutePath() + File.separator + file.getName();
            if (file.isDirectory()) {
                newPath = newPath + File.separator;
            }
