import java.util.ArrayList;
import java.util.List;

public class Code {
    private List<String> codeLines;
    private int lineCount;

    public Code() {
        this.codeLines = new ArrayList<>();
        this.lineCount = 0;
    }

    public Code(List<String> codeLines) {
        this.codeLines = codeLines;
        this.lineCount = codeLines.size();
    }

    public List<String> getCodeLines() {
        return codeLines;
    }

    public void setCodeLines(List<String> codeLines) {
        this.codeLines = codeLines;
    }

    public int getLineCount() {
        return lineCount;
    }

    public void setLineCount(int lineCount) {
        this.lineCount = lineCount;
    }

    public void addLine(String line) {
        this.codeLines.add(line);
        this.lineCount++;
    }

    public void removeLine(int index) {
        this.codeLines.remove(index);
        this.lineCount--;
    }

    public void replaceLine(int index, String line) {
        this.codeLines.set(index, line);
    }

    public String getLine(int index) {
        return this.codeLines.get(index);
    }

    public void clear() {
        this.codeLines.clear();
        this.lineCount = 0;
    }
}
