	private BordersDAO dao;
	private Graph<Country, DefaultWeightedEdge> grafo;
	private Map<Integer, Country> idMap;
	private Map<Integer, Country> codeMap;
	
	public Model() {
		this.dao = new BordersDAO();
		this.grafo = new SimpleWeightedGraph<>(DefaultWeightedEdge.class);
		this.idMap = new HashMap<>();
		this.codeMap = new HashMap<>();
	}
	
	public List<Country> getCountries(){
		return dao.getAllCountries();
	}
	
	public void creaGrafo(int anno) {
		this.grafo = new SimpleWeightedGraph<>(DefaultWeightedEdge.class);
		this.idMap = new HashMap<>();
		this.codeMap = new HashMap<>();
		
		List<Country> countries = dao.getAllCountries();
		for(Country c : countries) {
			this.idMap.put(c.getCountryId(), c);
			this.codeMap.put(c.getCountryId(), c);
		}
		
		List<Border> bordi = dao.getAllBorders(anno);
		for(Border b : bordi) {
			Country c1 = this.idMap.get(b.getCountry1());
			Country c2 = this.idMap.get(b.getCountry2());
			Graphs.addEdgeWithVertices(this.grafo, c1, c2, b.getWeight());
		}
	}
	
	public int getNVertici() {
		return this.grafo

