import it.polito.tdp.extflightdelays.db.ExtFlightDelaysDAO;

public class Model {
	
	private ExtFlightDelaysDAO dao;
	private Graph<Airport, DefaultWeightedEdge> grafo;
	private Map<Integer, Airport> idMap;
	private List<Airport> airports;
	private List<Flight> flights;
	private List<Airline> airlines;
	private List<Airport> airportsOrdinate;
	
	public Model() {
		this.dao = new ExtFlightDelaysDAO();
		this.grafo = new SimpleWeightedGraph<>(DefaultWeightedEdge.class);
		this.idMap = new HashMap<>();
		this.airports = new ArrayList<>();
		this.flights = new ArrayList<>();
		this.airlines = new ArrayList<>();
		this.airportsOrdinate = new ArrayList<>();
	}
	
	public void creaGrafo() {
		this.airports = this.dao.getAllAirports();
		this.flights = this.dao.getAllFlights();
		this.airlines = this.dao.getAllAirlines();
		
		for(Airport a : this.airports) {
			this.idMap.put(a.getId(), a);
			Graphs.addVertex(this.grafo, a);
		}
		
		for(Flight f : this.flights) {
			Graphs.addEdge(this.grafo, this.idMap.get(f.getOrigin()), this.idMap.get(f.getDestination()), f.getDistance());
		}

}

