package com.github.seanprashad.codewars.kata.8kyu;

import java.util.HashMap;
import java.util.Map;

/**
 * Counting Duplicates
 *
 * <p>Write a function that will return the count of distinct case-insensitive alphabetic characters and numeric digits that occur more than once in the input string. The input string can be assumed to contain only alphabets (both uppercase and lowercase) and numeric digits.
 *
 * <p>Example
 *
 * <p>"abcde" -> 0 # no characters repeats more than once
 *
 * <p>"aabbcde" -> 2 # 'a' and 'b'
 *
 * <p>"aabBcde" -> 2 # 'a' occurs twice and 'b' twice (`b` and `B`)
 *
 * <p>"indivisibility" -> 1 # 'i' occurs six times
 *
 * <p>"Indivisibilities" -> 2 # 'i' occurs seven times and's' occurs twice
 *
 * <p>"aA11" -> 2 # 'a' and '1'
 *
 * <p>"ABBA" -> 2 # 'A' and 'B' each occur twice
 */
public class CountingDuplicates {

  public static int duplicateCount(String text) {
    Map<Character, Integer> map = new HashMap<>();
    for (char c : text.toLowerCase().toCharArray()) {
      if (map.containsKey(c)) {
        map.put(c, map.get(c) + 1);
      } else {
        map.put(c, 1);
      }
    }
    return map.values().stream().filter(i -> i > 1).mapToInt(i -> i).sum();
  }
}
