package com.github.javaparser.ast.expr;

import com.github.javaparser.ast.Node;
import com.github.javaparser.ast.NodeList;
import com.github.javaparser.ast.visitor.VoidVisitor;

/**
 * A binary expression.
 * 
 * @author 
 *
 */
public class BinaryExpr extends Expr {

    private final NodeList<Expr> operands;
    private final BinaryOperator operator;

    /**
     * @param operator
     *            the operator of this binary expression
     * @param operands
     *            the operands of this binary expression
     */
    public BinaryExpr(BinaryOperator operator, Expr... operands) {
        this(operator, new NodeList<Expr>(operands));
    }

    /**
     * @param operator
     *            the operator of this binary expression
     * @param operands
     *            the operands of this binary expression
     */
    public BinaryExpr(BinaryOperator operator, NodeList<Expr> operands) {
        this.operator = operator;
        this.operands = operands;
    }

    /**
     * @return the operator of this binary expression
     */
    public BinaryOperator getOperator() {
        return operator;
    }

    /**
     * @return the operands of this binary expression
     */
    public NodeList<Expr> getOperands() {
        return operands;
    }

    @Override
    public <R, A> R accept(VoidVisitor<R, A> v, A arg) {
        return v.visit(this, arg);
    }

    @Override
    public String toString() {
        return operands.toString() + " " + operator.toString() + " " + operands.getLast().toString();
    }
}
