package com.github.sukulangi.codefights.arcade.intro.level1;

import java.util.Arrays;

/**
 * <a href="https://codefights.com/arcade/intro/level-1/Y76r2r86w274z4g8q">Add Border</a>
 *
 * @author 
 */
public class AddBorder {
    public static String[] addBorder(String[] picture) {
        int len = picture[0].length();
        String[] result = new String[picture.length + 2];
        result[0] = result[result.length - 1] = new String(new char[len + 2]).replace("\0", "*");
        for (int i = 1; i < result.length - 1; i++) {
            result[i] = "*" + picture[i - 1] + "*";
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(addBorder(new String[]{"abc", "ded"})));
    }
}
