public class exo1 {
    public static void main(String[] args) {
        Path path = Paths.get("src/main/resources/exo1");
        try (Stream<Path> stream = Files.walk(path)) {
            List<Path> files = stream
                   .filter(p -> p.toFile().isFile())
                   .collect(Collectors.toList());
            List<String> lines = new ArrayList<>();
            for (Path file : files) {
                try (Stream<String> stream2 = Files.lines(file)) {
                    lines.addAll(stream2.collect(Collectors.toList()));
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            System.out.println(lines);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
