package com.github.hcsp.io;

import java.io.File;
import java.io.FileFilter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class FileSearch {
    /**
     * 给定一个目录，使用迭代的方式返回所有以.java为后缀的文件
     *
     * 例如，给定目录为"dir"，则有如下文件：
     *
     * - dir/a.java
     * - dir/b.java
     * - dir/c/d.java
     * - dir/c/e.java
     * - dir/c/f.java
     *
     * 返回一个List，包含dir/a.java, dir/b.java, dir/c/d.java, dir/c/e.java, dir/c/f.java
     *
     * @param dir 要搜索的目录
     * @return 所有.java文件在目录树中所对应的File列表
     */
    public static List<File> search(File dir) {
        List<File> files = new ArrayList<>();
        search(dir, files);
        return files;
    }

    public static void search(File dir, List<File> files) {
        File[] filesInDir = dir.listFiles();
        if (filesInDir == null) {
            return;
        }
        for (File file : filesInDir) {
            if (file.isDirectory()) {
                search(file, files);
            } else if (file.getName().endsWith(".java")) {
                files.add(file);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        File projectDir = new File(System.getProperty("basedir", System.getProperty("user.dir")));
        System.out.println(
                search(new File(projectDir, "src/main/java/com/github/hcsp/io")).stream().map(File::getPath).toArray());
    }
}
