package com.github.shayank.codewars.kyu5;

import java.util.Arrays;

/**
 * You are given an array (which will have a length of at least 3, but could be
 * very large) containing integers. The array is either entirely comprised of
 * odd integers or entirely comprised of even integers except for a single
 * integer N. Write a method that takes the array as an argument and returns this
 * "outlier" N.
 * 
 * Examples
 * [2, 4, 0, 100, 4, 11, 2602, 36]
 * Should return: 11 (the only odd number)
 * 
 * [160, 3, 1719, 19, 11, 13, -21]
 * Should return: 160 (the only even number)
 * 
 * @author shayank
 *
 */
public class FindTheOddInt {

	public static void main(String[] args) {
		System.out.println(findIt(new int[] { 2, 4, 0, 100, 4, 11, 2602, 36 }));
		System.out.println(findIt(new int[] { 160, 3, 1719, 19, 11, 13, -21 }));
	}

	public static int findIt(int[] arr) {
		Arrays.sort(arr);
		int odd = 0;
		int even = 0;
		for (int i = 0; i < arr.length; i++) {
			if (arr[i] % 2 == 0) {
				even++;
			} else {
				odd++;
			}
		}
		return odd > even? arr[arr.length - 1] : arr[0];
	}

}
