package com.github.michaelruocco.codefights.arcade.intro;

import java.util.stream.IntStream;

/**
 * https://codefights.com/arcade/intro/level-1/72n462686j9v79v4q
 */
public class isLucky {
    public static boolean isLucky(int n) {
        int sum1 = IntStream.range(0, n / 2)
               .map(i -> n % 10)
               .sum();
        int sum2 = IntStream.range(n / 2, n)
               .map(i -> n % 10)
               .sum();
        return sum1 == sum2;
    }
}
