/**
 * https://codefights.com/arcade/intro/level-1/72n462686j9v79v4q
 */
public class checkPalindrome {
    public static boolean checkPalindrome(String inputString) {
        return IntStream.range(0, inputString.length() / 2)
               .allMatch(i -> inputString.charAt(i) == inputString.charAt(inputString.length() - 1 - i));
    }
}
