package fr.umlv.java.mailcap;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;

public class Mailcap {
    private static final String MAILCAP_FILE = "/etc/mailcap";
    private static final String DEFAULT_COMMAND = "xdg-open";
    private static final String DEFAULT_MIME_TYPE = "application/octet-stream";

    private static final Map<String, String> mimeTypes = new HashMap<>();
    private static final Map<String, String> commands = new HashMap<>();

    static {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Mailcap.class.getResourceAsStream(MAILCAP_FILE)))) {
            String line;
            while ((line = reader.readLine())!= null) {
                String[] split = line.split(";");
                String mimeType = split[0];
                String command = split[1];
                if (mimeType.equals(DEFAULT_MIME_TYPE)) {
                    continue;
                }
                mimeTypes.put(mimeType, command);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static String findMatch(String mimeType) {
        if (mimeTypes.containsKey(mimeType)) {
            return mimeTypes.get(mimeType);
        }
        return DEFAULT_COMMAND;
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Usage: java -jar mailcap.jar <mime_type>");
            return;
        }
        String command = findMatch(args[0]);
        try {
            Process process = Runtime.getRuntime().exec(command);
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
