                if (command.startsWith(COMMAND_PREFIX) && command.endsWith(COMMAND_SUFFIX)) {
                    command = command.substring(COMMAND_PREFIX.length(), command.length() - COMMAND_SUFFIX.length());
                    mimeTypes.put(mimeType, command);
                }
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public String findMatch(String mimeType) {
        return mimeTypes.get(mimeType);
    }
