    public NodeList<VariableDeclarator> getVariableDeclarators() {
        return variableDeclarators;
    }

    public NodeList<Expression> getExpressions() {
        return expressions;
    }

    public void setVariableDeclarators(NodeList<VariableDeclarator> variableDeclarators) {
        this.variableDeclarators = variableDeclarators;
