    public void setExpressions(NodeList<Expression> expressions) {
        this.expressions = expressions;
    }

    @Override
    public <R, A> R accept(VoidVisitor<R, A> visitor, A data) {
        return visitor.visit(this, data);
    }

    @Override
    public Node clone() {
        return new AssignExpr(variableDeclarators.clone(), expressions.clone());
    }

    @Override
