    public static void main(String[] args) throws IOException {
        if (args.length!= 1) {
            System.err.println("Usage: java -jar mailcap.jar <mime_type>");
            System.exit(1);
        }

        String mime_type = args[0];
        List<String> lines = Files.readAllLines(Paths.get(MAILCAP_FILE));

        Pattern pattern = Pattern.compile("^([^;]+);(.*)");
        Matcher matcher;
        for (String line : lines) {
            matcher = pattern.matcher(line);
            if (matcher.matches()) {
                if (matcher.group(1).equals(mime_type)) {
                    System.out.println(matcher.group(2));
                    break;
                }
            }
        }
    }
}
