		this.dao = new DAO();
		this.mailcap = new ArrayList<>();
		this.mime_type = new ArrayList<>();
		this.mailcap_mime_type = new ArrayList<>();
	}

	public List<String> getMailcap() {
		return this.mailcap;
	}

	public List<String> getMime_type() {
		return this.mime_type;
	}

	public List<String> getMailcap_mime_type() {
		return this.mailcap_mime_type;
	}

	public void creaMailcap() {
		this.mailcap = this.dao.getAllMailcap();
	}

	public void creaMime_type() {
		this.mime_type = this.dao.getAllMime_type();
	}

	public void creaMailcap_mime_type() {
		this.mailcap_mime_type = this.dao.getAllMailcap_mime_type();
	}

	public String trovaMime_type(String mailcap) {
		for (String s : this.mailcap_mime_type) {
			if (s.startsWith(mailcap))
				return s.substring(mailcap.length() + 1);
		}
		return null;
	}

	public String trovaMailcap(String mime_type) {
		for (String s : this.mailcap_mime_type) {
			if (s.startsWith(mime_type))
				return s.substring(mime_type.length() + 1);
		}
		return null;
	}

}
