 * 
 * [160, 3, 1719, 19, 11, 13, -21]
 * Should return: 160 (the only even number)
 * </p>
 * <p>
 * [2, 4, 6, 8, 10, 3]
 * Should return: 3 (the only odd number)
 * 
 * [1, 2, 3, 4, 5, 6]
 * Should return: No Outlier
 * 
 * [2068, 1719, 8717, 99, 2068, 8139, 4495, 144]
 * Should return: 1719 (the only even number)
 * </p>
 * 
 * @author jcup
 *
 */
public class FindTheParityOutlier {

    public static int find(int[] integers) {
        int even = 0;
        int odd = 0;
        for (int i : integers) {
            if (i % 2 == 0) {
                even++;
            } else {
                odd++;
            }
        }
        return even > odd? Arrays.stream(integers).filter(i -> i % 2!= 0).findFirst().get() : Arrays.stream(integers).

