package de.hpi.proglang.mailcap;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Mailcap {
    /**
     * Simuliert die Funktion mailcap.findmatch. 
     * Konstruiert einen Befehl, um die Datei basierend auf dem mime_type anzuzeigen, und führt ihn aus.
     * 
     * Diese Implementierung enthält eine Überprüfung, um das Verketten von Befehlen zu verhindern, indem Semikolons blockiert werden.
     */
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        Map<String, String> mimeTypes = new HashMap<>();
        mimeTypes.put("text/plain", "cat");
        mimeTypes.put("text/html", "lynx");
        mimeTypes.put("application/pdf", "evince");
        mimeTypes.put("image/jpeg", "eog");

        String mime_type = reader.readLine();
        String command = mimeTypes.get(mime_type);

        if (command == null) {
            System.out.println("No application found for " + mime_type);
            return;
        }

        List<String> commandList = new ArrayList<>();
        commandList.add(command);
        commandList.add(reader.readLine());

        while (true) {
            String line = reader.readLine();
            if (line.isEmpty()) {
                break;
            }

            if (line.contains(";")) {
                System.out.println("Invalid command");
                return;
            }

            commandList.add(line);
        }

        String[] commandArray = commandList.toArray(new String[0]);
        ProcessBuilder pb = new ProcessBuilder(commandArray);
        pb.start();
    }
}
