package com.github.sevntu.checkstyle.checks.coding;

import com.puppycrawl.tools.checkstyle.api.AbstractCheck;
import com.puppycrawl.tools.checkstyle.api.DetailAST;
import com.puppycrawl.tools.checkstyle.api.TokenTypes;

/**
 * Checks for duplicate literals.
 *
 * @author 
 */
public class AvoidDuplicateLiteralsCheck extends AbstractCheck {

    private static final String MSG_DUPLICATE_LITERAL = "Duplicate literal: %s";

    @Override
    public int[] getDefaultTokens() {
        return new int[] { TokenTypes.LITERAL_STRING };
    }

    @Override
    public int[] getAcceptableTokens() {
        return new int[] { TokenTypes.LITERAL_STRING };
    }

    @Override
    public int[] getRequiredTokens() {
        return new int[] { TokenTypes.LITERAL_STRING };
    }

    @Override
    public void visitToken(DetailAST ast) {
        String literal = ast.getText();
        DetailAST parent = ast.getParent();
        while (parent!= null) {
            if (parent.getType() == TokenTypes.LITERAL_STRING) {
                if (parent.getText().equals(literal)) {
                    log(ast.getLineNo(), MSG_DUPLICATE_LITERAL, literal);
                }
            }
            parent = parent.getParent();
        }
    }
}
