import java.util.ArrayList;
import java.util.List;

public class J2SNodeBlock extends J2SNode {
    private final List<J2SNode> statements = new ArrayList<>();

    public J2SNodeBlock(J2SNode... statements) {
        for (J2SNode statement : statements) {
            this.statements.add(statement);
        }
    }

    public List<J2SNode> getStatements() {
        return statements;
    }

    @Override
    public <T> T accept(J2SVisitor<T> visitor) {
        return visitor.visit(this);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("{\n");
        for (J2SNode statement : statements) {
            sb.append(statement.toString());
        }
        sb.append("}");
        return sb.toString();
    }
}
