package com.github.tux21b.codewars.java.kyu8;

public class SumOfDigits {
    public static int digital_root(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum > 9? digital_root(sum) : sum;
    }
}
