package com.github.f4b6a3.codewars.solutions.kyu8;

import java.util.Arrays;

/**
 * <a href="https://www.codewars.com/kata/find-the-odd-int/train/java">Find the odd int</a>
 *
 * <p>Given an array, find the int that appears an odd number of times.
 *
 * <p>There will always be only one integer that appears an odd number of times.
 *
 * <p>Example:
 *
 * <p>Input: [1,1,2,-2,5,2,4,4,-1,-2,5]
 *
 * <p>Output: -1
 *
 * <p>Explanation: -1 appears 8 times and 8 is the odd number.
 */
public class FindTheOddInt {

  public static int findIt(int[] a) {
    Arrays.sort(a);
    int count = 1;
    int i = 0;
    while (i < a.length - 1) {
      if (a[i] == a[i + 1]) {
        count++;
      } else {
        if (count % 2!= 0) {
          return a[i];
        }
        count = 1;
      }
      i++;
    }
    return a[i];
  }
}
