package com.github.vlsidlyarevich.codewars.kyu6;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * https://www.codewars.com/kata/586538146135330bd1000392/train/java
 */
public class SimpleFun175_FindTheLongestWordInAString {
    public static int findLongestWord(String s) {
        List<String> words = Arrays.stream(s.split(" ")).collect(Collectors.toList());
        return words.stream().mapToInt(String::length).max().orElse(0);
    }
}
