 *
 * @author 
 */
public class FindTheParityOutlier {
    public static int find(int[] integers) {
        return IntStream.of(integers)
               .filter(i -> Arrays.stream(integers).filter(j -> j % 2 == i % 2).count() == 1)
               .findFirst()
               .orElseThrow(() -> new IllegalArgumentException("No outlier"));
    }
}
