package com.github.tong.codewars.kata.kyu6;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * <a href="https://www.codewars.com/kata/find-the-parity-outlier/train/java">Find the Parity Outlier</a>
 * 
 * @author tong
 *
 */
public class FindTheParityOutlier {
    public static int find(int[] integers) {
        List<Integer> odd = Arrays.stream(integers)
               .filter(i -> i % 2!= 0)
               .collect(Collectors.toList());
        List<Integer> even = Arrays.stream(integers)
               .filter(i -> i % 2 == 0)
               .collect(Collectors.toList());
        return odd.size() == 1? odd.get(0) : even.get(0);
    }
}
