package com.github.hcsp.io;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class FileSearch {
    // 找到指定目录及其子目录下所有.java文件，打印出文件的相对路径
    public static void main(String[] args) throws IOException {
        File projectDir = new File(System.getProperty("basedir", System.getProperty("user.dir")));
        System.out.println(findFile(projectDir, ".java").toString());
    }

    public static List<File> findFile(File root, String suffix) throws IOException {
        List<File> files = new ArrayList<>();
        if (root.isDirectory()) {
            File[] subFiles = root.listFiles();
            if (subFiles!= null) {
                for (File file : subFiles) {
                    files.addAll(findFile(file, suffix));
                }
            }
        } else if (root.isFile()) {
            if (root.getName().endsWith(suffix)) {
                files.add(root);
            }
        }
        return files;
    }
}
