public class FileSearch {
    /**
     * 给定一个目录，返回一个存储在该目录下的所有Java源文件的绝对路径。
     *
     * 例如，给定目录为"D:\\github\\java-advanced-2020"，应返回{"D:\\github\\java-advanced-2020\\src\\main\\java\\com\\github\\hcsp\\io\\FileSearch.java"}。
     *
     * <p>注意，不要求查找所有Java源文件，只要是<b>后缀名为.java</b>的即可，例如<b>Hello.java</b>、<b>Hello.java.bak</b>等。
     *
     * <p>请使用<b>广度优先搜索</b>算法。
     *
     * @param root 根目录
     * @return 所有Java源文件绝对路径
     */
    public List<String> search(String root) throws IOException {
        File file = new File(root);
        List<String> result = new ArrayList<>();
        List<File> files = new ArrayList<>();
        files.add(file);
        while (!files.isEmpty()) {
            File f = files.remove(0);
            if (f.isDirectory()) {
                File[] fs = f.listFiles();
                if (fs!= null) {
                    files.addAll(Arrays.asList(fs));
                }
            } else {
                if (f.getName().endsWith(".java")) {
                    result.add(f.getAbsolutePath());
                }
            }
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        System.out.println(new FileSearch().search("D:\\github\\java-advanced-2020"));
    }
}
