import com.github.javaparser.ast.type.Type;
import com.github.javaparser.ast.visitor.VoidVisitor;

import java.util.List;

public class VariableDeclarationExpr extends Expression implements BodyDeclaration {

    private Type type;
    private List<VariableDeclarator> variables;
    private NodeList<Comment> comments;

    public VariableDeclarationExpr(Type type, List<VariableDeclarator> variables) {
        this.type = type;
        this.variables = variables;
    }

    public Type getType() {
        return type;
    }

    public void setType(Type type) {
        this.type = type;
    }

    public List<VariableDeclarator> getVariables() {
        return variables;
    }

    public void setVariables(List<VariableDeclarator> variables) {
        this.variables = variables;
    }

    public NodeList<Comment> getComments() {
        return comments;
    }

    public void setComments(NodeList<Comment> comments) {
        this.comments = comments;
    }

    @Override
    public <R, A> R accept(VoidVisitor<R, A> v, A arg) {
        return v.visit(this, arg);
    }

    @Override
    public String toString() {
        return "VariableDeclarationExpr{" +
                "type=" + type +
                ", variables=" + variables +
                ", comments=" + comments +
                '}';
    }
}
