     *
     * 例如，传入["apple","pear","orange"]，返回["apple","orange","pear"]。
     *
     * 请不要使用Java内置的排序函数。
     */
    public static List<String> sort(String[] strings) {
        List<String> list = new ArrayList<>();
        for (String s : strings) {
            list.add(s);
        }
        list.sort(new StringLengthComparator());
        return list;
    }

    public static void main(String[] args) {
        System.out.println(sort(new String[] {"apple", "pear", "orange"}));
    }
}
