package com.github.wolf99999.codewars.kyu8;

import java.util.Arrays;

/**
 * https://www.codewars.com/kata/57b06f90e298a7b53d000a86
 */
public class The_Supermarket_Queue {
    public static int queueTime(int[] customers, int n) {
        int[] tills = new int[n];
        for (int i = 0; i < customers.length; i++) {
            int min = 0;
            int minIndex = 0;
            for (int j = 0; j < n; j++) {
                if (tills[j] < tills[minIndex]) {
                    min = tills[j];
                    minIndex = j;
                }
            }
            tills[minIndex] += customers[i];
        }
        return Arrays.stream(tills).max().getAsInt();
    }
}
