package com.github.jimschubert.math.parser;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import com.github.jimschubert.math.parser.token.Token;
import com.github.jimschubert.math.parser.token.TokenFactory;
import com.github.jimschubert.math.parser.token.TokenType;

public class MathParser {
    private static final Pattern PATTERN = Pattern.compile("([\\d\\+\\-\\*\\/\\(\\)\\^\\s]+)");

    private final TokenFactory tokenFactory;

    public MathParser(TokenFactory tokenFactory) {
        this.tokenFactory = tokenFactory;
    }

    public List<Token> parse(String expression) {
        Matcher matcher = PATTERN.matcher(expression);
        List<Token> tokens = new ArrayList<>();
        while (matcher.find()) {
            String token = matcher.group();
            if (token.length() == 0) {
                continue;
            }
            tokens.add(tokenFactory.createToken(token));
        }
        return tokens;
    }

    public static void main(String[] args) {
        MathParser parser = new MathParser(new TokenFactory());
        List<Token> tokens = parser.parse("1 + 2 * 3");
        System.out.println(tokens);
    }
}
