package com.github.dmytrodanylyk.codefights.arcade.intro.level1;

import java.util.Arrays;

public class AddBorder {
    String[] addBorder(String[] picture) {
        int width = picture[0].length() + 2;
        String[] result = new String[picture.length + 2];
        for (int i = 0; i < result.length; i++) {
            if (i == 0 || i == result.length - 1) {
                result[i] = new String(new char[width]).replace("\0", "*");
            } else {
                result[i] = "*" + picture[i - 1] + "*";
            }
        }
        return result;
    }

    public static void main(String[] args) {
        AddBorder solution = new AddBorder();
        System.out.println(Arrays.toString(solution.addBorder(new String[]{"abc", "ded"})));
    }
}
