package il.co.topq.codewars.kata.kyu7;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class EasyBalance {
    public static String balance(String s) {
        List<String> list = Arrays.stream(s.split(" "))
               .map(String::trim)
               .collect(Collectors.toList());
        int sum = 0;
        for (String str : list) {
            sum += Integer.parseInt(str);
        }
        return sum == 0? "Balance: 0" : "Balance: " + sum;
    }
}
