package il.co.topq.codewars.kata.kyu7;

public class FindTheNextPerfectSquare {
    public static int findNextSquare(int sq) {
        int sqrt = (int) Math.sqrt(sq);
        return sqrt * sqrt == sq? (sqrt + 1) * (sqrt + 1) : -1;
    }
}
