package ru.spbau.mit.java.task1;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Task1 {
    /**
     * Возвращает список всех файлов, которые содержат заданную строку.
     * 
     * @param root Директория, в которой искать файлы.
     * @param search Строка, которую нужно найти.
     * @return Список файлов, в которых найдена строка.
     * @throws IOException Если произошла ошибка при чтении директории.
     */
    public static List<String> findFiles(String root, String search) throws IOException {
        List<String> result = new ArrayList<>();
        findFiles(root, search, result);
        return result;
    }

    private static void findFiles(String root, String search, List<String> result) throws IOException {
        String[] files = new String[0];
        try {
            files = new String[0];
            files = new java.io.File(root).list();
        } catch (Exception e) {
            throw new IOException("Can't read directory " + root);
        }
        for (String file : files) {
            String path = root + "/" + file;
            if (new java.io.File(path).isDirectory()) {
                findFiles(path, search, result);
            } else {
                String content = readFile(path);
                if (content.contains(search)) {
                    result.add(path);
                }
            }
        }
    }

    private static String readFile(String path) throws IOException {
        java.io.File file = new java.io.File(path);
        java.io.FileReader reader = new java.io.FileReader(file);
        StringWriter writer = new StringWriter();
        int c;
        while ((c = reader.read())!= -1) {
            writer.write(c);
        }
        reader.close();
        return writer.toString();
    }
}
