package com.github.khoi.utils;

import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import com.github.khoi.model.Question;
import com.github.khoi.model.QuestionType;

public class Utils {
    public static List<Question> getQuestions(String path) throws IOException {
        List<Question> questions = new ArrayList<>();
        File file = new File(path);
        if (!file.exists()) {
            throw new IOException("File not found");
        }
        BufferedReader reader = new BufferedReader(new InputStreamReader(Utils.class.getResourceAsStream(path)));
        String line;
        while ((line = reader.readLine())!= null) {
            if (line.startsWith("<|")) {
                String[] split = line.split("\\|");
                Question question = new Question();
                question.setQuestion(split[1]);
                question.setAnswer(split[2]);
                question.setQuestionType(QuestionType.valueOf(split[3]));
                questions.add(question);
            }
        }
        reader.close();
        return questions;
    }

