package com.github.jeppest.codewars.kata.java.kyu7;

public class SumOfPositive {
    public static int positive_sum(int[] arr) {
        int sum = 0;
        for (int i : arr) {
            if (i > 0) {
                sum += i;
            }
        }
        return sum;
    }
}
