package com.github.kodu.codewars.kata.kyu8;

import java.util.Arrays;

/**
 * <a href="https://www.codewars.com/kata/vowel-count">Vowel Count</a>
 *
 * <p>Return the number (count) of vowels in the given string.
 *
 * <p>We will consider a, e, i, o, u as vowels for this Kata (but not y).
 *
 * <p>The input string will only consist of lower case letters and/or spaces.
 *
 * <p>Examples:
 *
 * <p>vowel_count(&quot;abracadabra&quot;) == 5
 *
 * <p>vowel_count(&quot;codewars&quot;) == 3
 */
public class VowelCount {
  public static int getCount(String str) {
    return (int) Arrays.stream(str.split("")).filter(c -> "aeiou".contains(c)).count();
  }
}
