import java.util.function.Function;

/**
 * A result of a computation.
 *
 * @param <T> the type of the result
 * @param <E> the type of the error
 */
public interface Result<T, E> {
    /**
     * Returns the result of this computation.
     *
     * @return the result of this computation
     */
    T get();

    /**
     * Returns the error of this computation.
     *
     * @return the error of this computation
     */
    E getError();

    /**
     * Returns the result of this computation, or the default value if this computation
     * is an error.
     *
     * @param defaultValue the default value to return if this computation is an error
     * @return the result of this computation, or the default value if this computation
     *         is an error
     */
    default T orElse(T defaultValue) {
        return isOk()? get() : defaultValue;
    }

    /**
     * Returns the result of this computation, or the result of applying the given function
     * if this computation is an error.
     *
     * @param function the function to apply if this computation is an error
     * @return the result of this computation, or the result of applying the given function
     *         if this computation is an error
     */
    default T orElse(Function<E, T> function) {
        return isOk()? get() : function.apply(getError());
    }

    /**
     * Returns the result of this computation, or the result of applying the given function
     * if this computation is an error.
