package com.softuni.exam.web.controllers;

import com.softuni.exam.domain.models.binding.HomeBindingModel;
import com.softuni.exam.domain.models.service.HomeServiceModel;
import com.softuni.exam.domain.models.view.HomeViewModel;
import com.softuni.exam.services.HomeService;
import org.modelmapper.ModelMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.servlet.ModelAndView;

import java.util.List;

@Controller
public class HomeController {

    private final HomeService homeService;
    private final ModelMapper modelMapper;

    @Autowired
    public HomeController(HomeService homeService, ModelMapper modelMapper) {
        this.homeService = homeService;
        this.modelMapper = modelMapper;
    }

    @GetMapping("/")
    public ModelAndView index(ModelAndView modelAndView) {
        List<HomeServiceModel> homes = this.homeService.findAll();
        List<HomeViewModel> homeViewModels = this.modelMapper.map(homes, List.class);
        modelAndView.addObject("homes", homeViewModels);
        modelAndView.setViewName("home/index");
        return modelAndView;
    }

    @GetMapping("/home/create")
    public ModelAndView create(ModelAndView modelAndView) {
        modelAndView.setViewName("home/create");
        return modelAndView;
    }

    @PostMapping("/home/create")
    public ModelAndView createConfirm(@ModelAttribute HomeBindingModel homeBindingModel) {
        this.homeService.create(homeBindingModel);
        return new ModelAndView("redirect:/");
    }
}
