package com.github.pnowy.codewars.katas.java.kyu8;

import java.util.Arrays;

/**
 * <a href="https://www.codewars.com/kata/54da5a58ea159efa38000836">Find the odd int</a>
 *
 * <p>Given an array, find the int that appears an odd number of times.
 *
 * <p>There will always be only one integer that appears an odd number of times.
 *
 * <p>Example:
 *
 * <p>Input: [1,1,2,-2,5,2,4,4,-1,-2,5]
 *
 * <p>Output: -1
 *
 * <p>Explanation: -1 appears 8 times and 8 is the odd number.
 *
 * <p>Note:
 *
 * <p>Your solution should have a linear runtime complexity (O(n)).
 *
 * <p>Could you implement it without using extra memory?
 */
public class FindTheOddInt {

  public static int findIt(int[] a) {
    Arrays.sort(a);
    int count = 1;
    for (int i = 1; i < a.length; i++) {
      if (a[i] == a[i - 1]) {
        count++;
      } else {
        if (count % 2!= 0) {
          return a[i - 1];
        }
        count = 1;
      }
    }
    return a[a.length - 1];
  }
}
