package com.github.shanemcd.codewars.kyu6;

import java.util.stream.IntStream;

public class IsItPrime {
    /**
     * Write a function that takes a positive integer and returns true if it is a prime number, false if it is not.
     * 
     * The first two prime numbers are 2 and 3. After that, a prime number is only evenly divisible by 2 and itself.
     * 
     * Note: The range of the input will be between 2 and 2^31 - 1 (inclusive).
     */
    public boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        return IntStream.range(2, num).noneMatch(i -> num % i == 0);
    }
}
