    List<Integer> result = new ArrayList<>();
    for (int i = 0; i < list.size(); i++) {
        int min = list.get(i);
        int index = i;
        for (int j = i + 1; j < list.size(); j++) {
            if (list.get(j) < min) {
                min = list.get(j);
                index = j;
            }
        }
        result.add(min);
        list.set(index, list.get(i));
        list.set(i, min);
    }
    return result;
}
