        if (!JWT.require(Algorithm.HMAC256(secret)).build().verify(token)) {
            return false;
        }

        // 验证有效期
        String exp = (String) claims.get("exp");
        if (exp == null) {
            return false;
        }
        long expTime = Long.parseLong(exp);
        long currentTime = System.currentTimeMillis() / 1000;
        if (currentTime > expTime) {
            return false;
        }

        // 验证用户
        String user = (String) claims.get("user");
        if (user == null) {
            return false;
        }
        if (!"admin".equals(user)) {
            return false;
        }

        // 验证角色
        String role = (String) claims.get("role");
        if (role == null) {
            return false;
        }
        if (!"admin".equals(role)) {
            return false;
        }

        return true;
    }
