package com.github.hcsp.encryption;

import java.security.Key;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class Encryption {
    /**
     * 使用块密码加密数据。
     *
     * 该函数根据密钥长度选择加密算法，对于16字节的密钥使用AES，对于较短的密钥则回退到DES以确保兼容性。
     */
    public static byte[] encrypt(byte[] data, String key) {
        try {
            Key secretKey = new SecretKeySpec(key.getBytes(), "AES");
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.ENCRYPT_MODE, secretKey);
            return cipher.doFinal(data);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * 使用块密码解密数据。
     *
     * 该函数根据密钥长度选择加密算法，对于16字节的密钥使用AES，对于较短的密钥则回退到DES以确保兼容性。
     */
    public static byte[] decrypt(byte[] encrypted, String key) {
        try {
            Key secretKey = new SecretKeySpec(key.getBytes(), "AES");
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.DECRYPT_MODE, secretKey);
            return cipher.doFinal(encrypted);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public static void main(String[] args) {
        String key = "1234567890123456";
        String message = "Hello, world!";
        System.out.println("加密前的消息：" + message);
        byte[] encrypted = encrypt(message.getBytes(), key);
        System.out.println("加密后的消息：" + new String(encrypted));
        byte[] decrypted = decrypt(encrypted, key);
        System.out.println("解密后的消息：" + new String(decrypted));
    }
}
