package com.github.hcsp.multithread;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class MultiThread2 {
    // 一个包含100个元素的整型数组
    private static final int[] ARRAY = new int[100];

    // 一个线程安全的List，用于存储每个线程计算的结果
    private static final List<Integer> results = new ArrayList<>();

    // 一个线程安全的计数器，用于统计线程的个数
    private static final AtomicInteger count = new AtomicInteger(0);

    // 一个CountDownLatch，用于等待所有线程完成
    private static final CountDownLatch latch = new CountDownLatch(100);

    // 一个线程池，用于启动线程
    private static final ExecutorService pool = Executors.newFixedThreadPool(100);

    public static void main(String[] args) throws InterruptedException {
        // 启动100个线程，每个线程计算数组中从start到end的和
        for (int i = 0; i < 100; i++) {
            pool.execute(() -> {
                int start = count.getAndIncrement();
                int end = start + 10;
                int sum = 0;
                for (int i1 = start; i1 < end; i1++) {
                    sum += ARRAY[i1];
                }
                results.add(sum);
                latch.countDown();
            });
        }
        // 等待所有线程完成
        latch.await();
        // 关闭线程池
        pool.shutdown();
        // 等待线程池关闭
        pool.awaitTermination(1, TimeUnit.DAYS);
        // 打印结果
        System.out.println(results);
    }
}
