public class CodeAssistant {
    private User user;
    private List<Assistant> assistants;

    public CodeAssistant(User user) {
        this.user = user;
        this.assistants = new ArrayList<>();
    }

    public User getUser() {
        return user;
    }

    public void setUser(User user) {
        this.user = user;
    }

    public List<Assistant> getAssistants() {
        return assistants;
    }

    public void setAssistants(List<Assistant> assistants) {
        this.assistants = assistants;
    }

    public void addAssistant(Assistant assistant) {
        this.assistants.add(assistant);
    }

    public void removeAssistant(Assistant assistant) {
        this.assistants.remove(assistant);
    }

    public void addAssistant(AssistantType type) {
        Assistant assistant = AssistantFactory.createAssistant(type);
        this.assistants.add(assistant);
    }

    public void removeAssistant(AssistantType type) {
        Assistant assistant = AssistantFactory.createAssistant(type);
        this.assistants.remove(assistant);
    }

    public void addUser(UserType type) {
        User user = UserFactory.createUser(type);
        this.user = user;
    }

    public void removeUser(UserType type) {
        User user = UserFactory.createUser(type);
        this.user = user;
    }
}
