package com.github.wolfgarbe.test;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import com.github.wolfgarbe.test.model.Question;
import com.github.wolfgarbe.test.model.QuestionType;
import com.github.wolfgarbe.test.model.Test;
import com.github.wolfgarbe.test.model.TestType;

public class Test {

    public static void main(String[] args) throws IOException {
        Path path = Paths.get("src/main/resources/test.txt");
        List<String> lines = Files.readAllLines(path);
        List<Question> questions = new ArrayList<>();
        Test test = new Test();
        test.setType(TestType.JAVA);
        for (String line : lines) {
            if (line.startsWith("##")) {
                test.setName(line.substring(2));
            } else if (line.startsWith("###")) {
                String[] split = line.split(" ");
                Question question = new Question();
                question.setType(QuestionType.valueOf(split[1]));
                question.setNumber(Integer.parseInt(split[2]));
                question.setQuestion(line.substring(4));
                questions.add(question);
            } else if (line.startsWith("<|")) {
                String[] split = line.split(" ");
                Question question = questions.get(questions.size() - 1);
                question.setAnswer(split[1]);
                question.setAssistant(split[2]);
                question.setSystem(split[3]);
                question.setUser(split[4]);
            }
        }
        System.out.println(test);
    }

}
