import java.util.stream.Collectors;
import java.util.stream.IntStream;

/**
 * <a href="https://www.codewars.com/kata/mumbling/train/java">Mumbling</a>
 *
 * <p>This time no story, no theory. The examples below show you how to write function accum:
 *
 * <p>Examples:
 *
 * <p>accum("abcd") -> "A-Bb-Ccc-Dddd" accum("RqaEzty") -> "R-Qq-Aaa-Eeee-Zzzzz-Tttttt-Yyyyyyy" accum("cwAt") -> "C-Ww-Aaa-Tttt"
 *
 * <p>The parameter of accum is a string which includes only letters from a..z and A..Z.
 */
public class Mumbling {

  public static String accum(final String s) {
    return IntStream.range(0, s.length())
       .mapToObj(i -> s.substring(i, i + 1))
       .map(c -> c.toUpperCase() + c.toLowerCase().repeat(i -> i))
       .collect(Collectors.joining("-"));
  }
}
