package com.github.michal347.codewars.kata.kyu6;

import java.util.stream.IntStream;

/**
 * <a href="https://www.codewars.com/kata/541c8630095125aba6000c00/train/java">Sum of Digits / Digital Root</a>
 *
 * @author 
 */
public class SumOfDigitsDigitalRoot {
    public static int digital_root(int n) {
        return IntStream.of(String.valueOf(n).chars().map(c -> c - '0').toArray())
               .reduce(0, (a, b) -> a + b);
    }
}
