package com.github.jankroken.codewars.kata.kyu6;

import java.util.HashMap;
import java.util.Map;

/**
 * <a href="https://www.codewars.com/kata/vowel-count/java">Vowel Count</a>
 *
 * <p>Return the number (count) of vowels in the given string.
 *
 * <p>We will consider a, e, i, o, u as vowels for this Kata (but not y).
 *
 * <p>The input string will only consist of lower case letters and/or spaces.
 */
public class VowelCount {

  public static int getCount(String str) {
    Map<Character, Integer> vowels = new HashMap<>();
    vowels.put('a', 0);
    vowels.put('e', 0);
    vowels.put('i', 0);
    vowels.put('o', 0);
    vowels.put('u', 0);

    for (char c : str.toCharArray()) {
      if (vowels.containsKey(c)) {
        vowels.put(c, vowels.get(c) + 1);
      }
    }

    return vowels.get('a') + vowels.get('e') + vowels.get('i') + vowels.get('o') + vowels.get('u');
  }
}
