package de.codecentric.jass.model;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class CodeSnippetService {

    @Autowired
    private CodeSnippetRepository codeSnippetRepository;

    public List<CodeSnippet> findAll() {
        return codeSnippetRepository.findAll();
    }

    public CodeSnippet findById(Long id) {
        return codeSnippetRepository.findById(id).orElse(null);
    }

    public CodeSnippet save(CodeSnippet codeSnippet) {
        return codeSnippetRepository.save(codeSnippet);
    }

    public void deleteById(Long id) {
        codeSnippetRepository.deleteById(id);
    }
}
