package com.github.selimsef.codewars.kyu6;

import java.util.stream.IntStream;

/**
 * <a href="https://www.codewars.com/kata/sum-of-digits-digital-root/train/java">Sum of Digits / Digital Root</a>
 * 
 * @author 
 */
public class SumOfDigitsDigitalRoot {
    public static int digital_root(int n) {
        return n == 0? 0 : (n % 9 == 0? 9 : n % 9);
    }

    public static int digital_root(int n) {
        return IntStream.of(String.valueOf(n).chars().map(c -> c - '0').toArray())
               .reduce(0, (a, b) -> a + b);
    }
}
