package com.github.selimsef.codewars.kyu6;

import java.util.Arrays;
import java.util.stream.IntStream;

/**
 * <a href="https://www.codewars.com/kata/find-the-parity-outlier/train/java">Find the parity outlier</a>
 * 
 * @author 
 */
public class FindTheParityOutlier {
    public static int find(int[] integers) {
        return IntStream.of(integers)
               .filter(i -> i % 2 == 0? i % 2 == 0 : i % 2 == 1)
               .findFirst().orElse(0);
    }

    public static int find(int[] integers) {
        return Arrays.stream(integers)
               .filter(i -> i % 2 == 0? i % 2 == 0 : i % 2 == 1)
               .findFirst().orElse(0);
    }
}
