        this.user = user;
        this.system = system;
        this.assistant = assistant;
        this.userCode = userCode;
        this.systemCode = systemCode;
        this.assistantCode = assistantCode;
    }

    public String getUser() {
        return user;
    }

    public void setUser(String user) {
        this.user = user;
    }

    public String getSystem() {
        return system;
    }

    public void setSystem(String system) {
        this.system = system;
    }

    public String getAssistant() {
        return assistant;
    }

    public void setAssistant(String assistant) {
        this.assistant = assistant;
    }

    public List<String> getUserCode() {
        return userCode;
    }

    public void setUserCode(List<String> userCode) {
        this.userCode = userCode;
    }

    public List<String> getSystemCode() {
        return systemCode;
    }

    public void setSystemCode(List<String> systemCode) {
        this.systemCode = systemCode;
    }

    public List<String> getAssistantCode() {
        return assistantCode;
    }

    public void setAssistantCode(List<String> assistantCode) {
        this.assistantCode = assistantCode;
    }
}
