package com.github.shanemcd.code_challenge.service;

import com.github.shanemcd.code_challenge.model.Challenge;
import com.github.shanemcd.code_challenge.model.ChallengeStatus;
import com.github.shanemcd.code_challenge.model.User;
import com.github.shanemcd.code_challenge.repository.ChallengeRepository;
import com.github.shanemcd.code_challenge.repository.UserRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class ChallengeService {

    @Autowired
    private ChallengeRepository challengeRepository;

    @Autowired
    private UserRepository userRepository;

    public List<Challenge> getAllChallenges() {
        return challengeRepository.findAll();
    }

    public Challenge getChallengeById(Long id) {
        return challengeRepository.findById(id).orElse(null);
    }

    public Challenge createChallenge(Challenge challenge) {
        return challengeRepository.save(challenge);
    }

    public Challenge updateChallenge(Challenge challenge) {
        return challengeRepository.save(challenge);
    }

    public Challenge deleteChallenge(Long id) {
        Challenge challenge = challengeRepository.findById(id).orElse(null);
        challengeRepository.delete(challenge);
        return challenge;
    }

    public List<Challenge> getChallengesByStatus(ChallengeStatus status) {
        return challengeRepository.findByStatus(status);
    }

    public List<Challenge> getChallengesByStatusAndUser(ChallengeStatus status, User user) {
        return challengeRepository.findByStatusAndUser(status, user);
    }

    public List<Challenge> getChallengesByStatusAndUser(ChallengeStatus status, Long userId) {
        User user = userRepository.findById(userId).orElse(null);
        return challengeRepository.findByStatusAndUser(status, user);
    }
}
