package hu.bme.mit.train.railway;

import java.util.ArrayList;
import java.util.List;

public class Train {
    private List<Station> stations;
    private int currentStationIndex;

    public Train(Station startStation) {
        stations = new ArrayList<>();
        stations.add(startStation);
        currentStationIndex = 0;
    }

    public void addStation(Station station) {
        stations.add(station);
    }

    public void move(int distance) {
        if (distance < 0) {
            throw new IllegalArgumentException("Distance must be positive.");
        }
        if (distance == 0) {
            return;
        }
        if (stations.size() == 0) {
            throw new IllegalArgumentException("No stations in the train.");
        }
        if (currentStationIndex + distance >= stations.size()) {
            throw new IllegalArgumentException("Cannot move the train further.");
        }
        currentStationIndex += distance;
    }

    public Station getCurrentStation() {
        return stations.get(currentStationIndex);
    }

    public int getDistance() {
        return currentStationIndex;
    }

    public int getStationCount() {
        return stations.size();
    }

