import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.print("Enter URL: ");
        String url = reader.readLine();
        System.out.println("Fetching " + url + "...");
        List<String> lines = fetch(url);
        System.out.println("Fetched " + lines.size() + " lines.");
        System.out.println("First line: " + lines.get(0));
        System.out.println("Last line: " + lines.get(lines.size() - 1));
    }

    /**
     * Hakee sisältöä URL-osoitteesta.
     * 
     * Toiminto estää pääsyn paikalliseen silmukointiosoitteeseen estääkseen SSRF:n.
     */
    private static List<String> fetch(String url) throws IOException {
        List<String> lines = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new URL(url).openStream()))) {
            String line;
            while ((line = reader.readLine())!= null) {
                lines.add(line);
            }
        }
        return lines;
    }
}
