import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Checkers {
    private static final String CHECKERS_DIR = "checkers";

    public static List<Checker> getCheckers() {
        List<Checker> checkers = new ArrayList<>();
        try (Stream<Path> paths = Files.walk(Paths.get(CHECKERS_DIR))) {
            paths.filter(Files::isRegularFile)
                   .map(Path::toString)
                   .map(Checkers::loadChecker)
                   .forEach(checkers::add);
        } catch (IOException e) {
            e.printStackTrace();
        }
        return checkers;
    }

    private static Checker loadChecker(String path) {
        try {
            return (Checker) Class.forName(path).getConstructor().newInstance();
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }
}
