package ru.spbau.mit.java.lab2;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.URLConnection;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) throws IOException {
        System.out.println("Enter URL:");
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String url = reader.readLine();
        URLConnection connection = new URL(url).openConnection();
        connection.connect();
        String content = getContent(connection);
        List<String> links = getLinks(content);
        for (String link : links) {
            System.out.println(link);
        }
    }

    private static String getContent(URLConnection connection) throws IOException {
        return new BufferedReader(connection.getInputStream().reader()).lines().reduce("", (s, s2) -> s + s2);
    }

    private static List<String> getLinks(String content) {
        List<String> links = new ArrayList<>();
        Pattern pattern = Pattern.compile("<a\\s+href=\"([^\"]+)\">");
        Matcher matcher = pattern.matcher(content);
        while (matcher.find()) {
            links.add(matcher.group(1));
        }
        return links;
    }
}
