public class CodeSnippetFactory {
    private static final String NEW_LINE = System.getProperty("line.separator");

    public static CodeSnippet createCodeSnippet(InputStream inputStream) throws IOException {
        CodeSnippet codeSnippet = new CodeSnippet("");
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        String line;
        int lineNumber = 1;
        List<String> lines = new ArrayList<>();
        while ((line = reader.readLine())!= null) {
            codeSnippet.addLine(line);
            codeSnippet.addLineNumber(lineNumber + "");
            lines.add(line);
            lineNumber++;
        }
        codeSnippet.setLines(lines);
        return codeSnippet

}
