	private String content;
	private List<Xpl> children;
	private Xpl parent;

	public Xpl(XplType type, String content) {
		this.type = type;
		this.content = content;
		this.children = new ArrayList<>();
	}

	public XplType getType() {
		return type;
	}

	public void setType(XplType type) {
		this.type = type;
	}

	public String getContent() {
		return content;
	}

	public void setContent(String content) {
		this.content = content;
	}

	public List<Xpl> getChildren() {
		return children;
	}

	public void setChildren(List<Xpl> children) {
		this.children = children;
	}

	public Xpl getParent() {
		return parent;
	}

	public void setParent(Xpl parent) {
		this.parent = parent;
	}

	@Override
	public String toString() {
		return "Xpl [type=" + type + ", content=" + content + ", children=" + children + ", parent=" + parent + "]";
	}
}
